const M_DEGRES = MS('dangers/explications-aux-degres-de-danger/orages', 'Degrés de danger orages');
const M_ALERTES = MS('meteo-et-climat-de-a-a-z/orage/les-alertes-d-orage', 'Les alertes d’orage');
const M_CANICULE = MS('dangers/recommandations-generales-sur-le-comportement-a-adopter/canicule', 'Recommandations de comportement : canicule');
const GE_RHONE = ['État de Genève, « Baignade du Rhône, soyez prudent ! »', 'https://www.ge.ch/baignade-du-rhone-soyez-prudent'];
const GE_ACCES = ['État de Genève, « Accès à l’eau et consignes de baignade »', 'https://www.ge.ch/plages-lieux-baignade-eaux-vives-geneve/acces-eau-consignes-baignade'];
const WP_PERMIS = ['Wikipédia (de), « Schiffsführerausweis »', 'https://de.wikipedia.org/wiki/Schiffsf%C3%BChrerausweis'];
const WP_SILVA = ['Wikipédia (de), « Silvaplanersee »', 'https://de.wikipedia.org/wiki/Silvaplanersee'];
const LOC = ['Mon Lac, loueurs vérifiés (chacun avec sa source)', 'https://monlac.ch/'];

const P = (...t) => t.map((x) => `<p>${x}</p>`).join('\n'), UL = (...t) => `<ul class="liste">\n${t.map((x) => `  <li>${x}</li>`).join('\n')}\n</ul>`;
const FIN = {
  fr: '<p>L’eau et le vent du moment, plage par plage, sont dans l’<a href="{app}">app Mon Lac</a>.</p>',
  en: '<p>The current water and wind, beach by beach, are in the <a href="{app}">My Lake app</a>.</p>',
  de: '<p>Wasser und Wind von heute, Badeplatz für Badeplatz, stehen in der <a href="{app}">App Mein See</a>.</p>',
  it: '<p>Acqua e vento del momento, spiaggia per spiaggia, sono nell’<a href="{app}">app Il mio lago</a>.</p>' };
const FIN_SANTE = {
  fr: '<p>Rien ici ne remplace un cours de secourisme ni l’avis d’un médecin. Urgence : 144 (ambulance), 117 (police), 112 (international).</p>',
  en: '<p>Nothing here replaces a first-aid course or a doctor’s advice. Emergency in Switzerland: 144 (ambulance), 117 (police), 112 (international).</p>',
  de: '<p>Nichts hier ersetzt einen Erste-Hilfe-Kurs oder ärztlichen Rat. Notruf: 144 (Sanität), 117 (Polizei), 112 (international).</p>',
  it: '<p>Nulla qui sostituisce un corso di primo soccorso o il parere di un medico. Emergenza: 144 (ambulanza), 117 (polizia), 112 (internazionale).</p>' };
// slug, image attendue, textes alternatifs, sources, santé, puis { fr: { titre, h1, desc, bref, s: [[h2, html], …] }, … } ; s peut être une fonction de la langue.
const A = (slug, img, altIA, sources, sante, t) => {
  const a = { slug, sante, img, altIA, sources };
  for (const L of LS) { const { s, ...x } = t[L]; a[L] = { ...x, html: () => `${s.map(([h, p]) => `<h2>${h}</h2>\n${p}`).join('\n')}\n${(sante ? FIN_SANTE : FIN)[L]}` }; }
  return a;
};

// Loueurs d'une ou plusieurs activités, groupés par lac (titre h2 = nom du lac). Liste vide : null.
const NOTE_LOC = { fr: 'Chaque fiche renvoie au site du loueur quand il existe. Horaires et prix changent : à confirmer auprès de lui.', en: 'Each entry links to the operator’s own website when there is one. Hours and prices change: check with them.', de: 'Jeder Eintrag führt auf die Website des Anbieters, wenn es eine gibt. Öffnungszeiten und Preise ändern sich: beim Anbieter nachfragen.', it: 'Ogni scheda rimanda al sito del gestore, quando esiste. Orari e prezzi cambiano: da confermare con lui.' };
const parLac = (acts) => {
  const g = {};
  for (const l of LOCATIONS) if (l.activites.some((a) => acts.includes(a))) (g[lacDe(SPOTS.find((s) => s.id === l.spot))] ??= []).push(l);
  return Object.entries(g).sort((p, q) => q[1].length - p[1].length);
};
const nbLoc = (acts) => parLac(acts).reduce((n, [, v]) => n + v.length, 0);
const sectionsLoc = (acts, L) => parLac(acts).map(([lac, v], i) => [nomLac(lac, L), `${i ? '' : `<p>${NOTE_LOC[L]}</p>\n`}<ul class="liste">\n${v.map((l) => ITEM(l, L)).join('\n')}\n</ul>`]);
const lacsDe = (acts, L) => parLac(acts).map(([lac]) => nomLac(lac, L)).join(', ');

const LIEN_PADDLE = { fr: 'Pour le Léman en détail : <a href="{blog:paddle-leman}">le paddle au Léman</a>.', en: 'Lake Geneva in detail: <a href="{blog:paddle-leman}">paddleboarding on Lake Geneva</a>.', de: 'Der Genfersee im Detail: <a href="{blog:paddle-leman}">Stand-up-Paddling am Genfersee</a>.', it: 'Il Lemano nel dettaglio: <a href="{blog:paddle-leman}">il paddle sul Lemano</a>.' };
const GILET_LIEN = { fr: 'Choisir son gilet : <a href="{blog:gilet-de-sauvetage-choisir}">les quatre types de gilets selon la SSS</a>.', en: 'Choosing a vest: <a href="{blog:gilet-de-sauvetage-choisir}">the four types of vest according to the SLRG</a>.', de: 'Die richtige Weste: <a href="{blog:gilet-de-sauvetage-choisir}">die vier Westentypen der SLRG</a>.', it: 'Scegliere il giubbotto: <a href="{blog:gilet-de-sauvetage-choisir}">i quattro tipi di giubbotto secondo la SSS</a>.' };

// Articles « louer » : une activité (ou un groupe), une ouverture, un conseil de prudence ; le reste vient des loueurs.
const louer = (slug, img, alt, acts, txt, extra = []) => {
  const n = nbLoc(acts);
  const t = {};
  for (const L of LS) { const x = txt[L](n, lacsDe(acts, L)); t[L] = { ...x, s: [...x.s, ...sectionsLoc(acts, L), ...(x.apres ?? [])] }; delete t[L].apres; }
  return A(slug, img, alt, [LOC, ...extra], false, t);
};

